INSERT INTO chemical_topic (id, title, shortDescription, narrativeIntro, iconKey, colorHex, orderIndex, minLevelToUnlock) VALUES ('estados', 'Materia y Estados', 'Sólidos, líquidos y gases en acción', 'El Laboratorio necesita tu ayuda para clasificar y transformar la materia.', 'topic_estados', '#2E7DFF', 1, 1);
INSERT INTO chemical_topic (id, title, shortDescription, narrativeIntro, iconKey, colorHex, orderIndex, minLevelToUnlock) VALUES ('mezclas', 'Mezclas', 'Combina sustancias virtuales y descubre qué pasa', 'Quimi guarda decenas de frascos mezclados. ¡Ayúdale a identificarlos!', 'topic_mezclas', '#14C7B4', 2, 1);
INSERT INTO chemical_topic (id, title, shortDescription, narrativeIntro, iconKey, colorHex, orderIndex, minLevelToUnlock) VALUES ('separacion', 'Separación', 'Filtra, decanta y evapora para recuperar sustancias', 'Algunas mezclas escondidas deben separarse antes de guardarse en la estantería.', 'topic_separacion', '#7ED957', 3, 2);
INSERT INTO chemical_topic (id, title, shortDescription, narrativeIntro, iconKey, colorHex, orderIndex, minLevelToUnlock) VALUES ('atomos', 'Átomos', 'Los bloques diminutos que forman todo', 'Un mapa gigante de átomos apareció en la pared del laboratorio.', 'topic_atomos', '#8B5CF6', 4, 2);
INSERT INTO chemical_topic (id, title, shortDescription, narrativeIntro, iconKey, colorHex, orderIndex, minLevelToUnlock) VALUES ('moleculas', 'Constructor Molecular', 'Une átomos y construye moléculas reales', 'La mesa de construcción molecular de Quimi espera tus creaciones.', 'topic_moleculas', '#FF6B4A', 5, 3);
INSERT INTO chemical_topic (id, title, shortDescription, narrativeIntro, iconKey, colorHex, orderIndex, minLevelToUnlock) VALUES ('reacciones', 'Reacciones Virtuales', 'Observa cambios seguros y predice resultados', 'Algo burbujea en la cámara de reacciones. ¿Puedes predecir qué ocurrirá?', 'topic_reacciones', '#FFC145', 6, 3);
