INSERT INTO atom (id, symbol, name, protons, electronsShellsCsv, category, colorHex, funFact, commonValence) VALUES ('H', 'H', 'Hidrógeno', 1, '1', 'NO_METAL', '#90CAF9', 'Es el átomo más ligero y el más abundante del universo.', 1);
